          fr: 'Oui, absolument. Vous pouvez faire une pause de 20 à 30 minutes dans une aire de repos moderne pour prier et manger. En sens inverse (Médine vers La Mecque), nous effectuons une halte gratuite au Miqat de Dhul Hulayfah (Bir Ali) pour l’Ihram.',
          es: 'Sí, por supuesto. Puede realizar una parada de 20 a 30 minutos en modernas áreas de servicio para rezar y comer. Si viaja en sentido inverso (Medina a La Meca) para la Umrah, ofrecemos una parada de cortesía en el Miqat de Dhul Hulayfah (Bir Ali).',
          de: 'Ja, absolut. Sie können eine 20- bis 30-minütige Pause an modernen Raststätten zum Beten und Essen einlegen. Bei umgekehrter Fahrt (Medina nach Mekka) zur Umrah ist der Halt am Mīqāt Dhul Hulayfah (Bir Ali) für den Ihram kostenlos inbegriffen.',
          hi: 'हाँ, बिल्कुल। आप नमाज और भोजन के लिए 20-30 मिनट आधुनिक रेस्ट एरिया पर रुक सकते हैं। यदि आप उल्टी दिशा (मदीना से मक्का) उमरा के लिए आ रहे हैं, तो मीक़ात ज़ुल-हुलैफ़ा (बीर अली) पर एहराम के लिए मुफ़्त ठहराव दिया जाता है।',
          tr: 'Evet, kesinlikle. Modern tesislerde namaz ve yemek için 20-30 dakika mola verebilirsiniz. Medine’den Mekke’ye umre için gidiyorsanız, Zülhuleyfe (Bir Ali) Mikatında ihram için ücretsiz mola verilir.',
