        ur: 'گاڑی میں 5 لیٹر آبِ زمزم کے ڈبے کہاں رکھے جاتے ہیں؟',
        fr: 'Où sont placés les cartons d’eau de Zamzam de 5 litres dans le véhicule ?',
        es: '¿Dónde se colocan las cajas de 5 litros de agua de Zamzam en el vehículo?',
        de: 'Wo werden die 5-Liter-Zamzam-Kartons im Fahrzeug verstaut?',
        hi: 'गाड़ी में 5 लीटर आब-ए-ज़मज़म के डिब्बे कहाँ रखे जाते हैं?',
