      answer: {
        ar: 'يتم وضع عبوات زمزم الرسمية المغلفة مسطحة ومثبتة في أرضية صندوق الأمتعة الخلفي لضمان سلامتها وعدم تعرضها للضغط أو الانسكاب، مع حظر وضعها فوق مقاعد الركاب لسلامة الجميع.',
        en: 'Official 5-liter boxed Zamzam containers are placed flat and securely on the flat cargo floor of the vehicle trunk to prevent tipping or leaking, never piled loosely on passenger seats.',
        ms: 'Kotak rasmi air Zamzam 5 liter diletakkan secara rata dan kukuh di atas lantai but kenderaan bagi mengelakkan tumpahan, dan tidak sesekali diletakkan di atas kerusi penumpang.',
        id: 'Kardus resmi air Zamzam 5 liter diletakkan mendatar dan stabil di lantai bagasi belakang untuk mencegah tumpah, dan tidak pernah ditaruh di atas kursi penumpang demi keselamatan.',
        ur: 'آبِ زمزم کے 5 لیٹر والے سرکاری کارٹن ڈگی کے فرش پر سیدھے اور محفوظ طریقے سے رکھے جاتے ہیں تاکہ وہ گریں یا چھلکیں نہیں، اور مسافروں کی نشستوں پر کبھی نہیں لادے جاتے۔',
        fr: 'Les cartons scellés officiels de 5 litres sont posés bien à plat et calés sur le plancher du coffre pour éviter tout risque de fuite, jamais empilés sur les sièges des passagers.',
        es: 'Las cajas oficiales de 5 litros de Zamzam se colocan planas y aseguradas en la base del maletero para evitar vuelcos, nunca amontonadas sobre los asientos de los pasajeros.',
        de: 'Die offiziellen 5-Liter-Kartons mit Zamzam-Wasser werden kippsicher und flach auf dem Ladeboden des Kofferraums platziert, niemals lose auf den Passagiersitzen.',
        hi: '5 लीटर आब-ए-ज़मज़म के आधिकारिक डिब्बों को डिक्की के फर्श पर सुरक्षित और सीधा रखा जाता है ताकि वे गिरे नहीं, और यात्रियों की सीटों पर कभी नहीं रखे जाते।',
        tr: 'Resmi 5 litrelik kutulu Zemzem bidonları dökülme ve devrilmeyi önlemek için bagaj zeminine düz ve güvenli şekilde yerleştirilir, yolcu koltuklarına asla konmaz.',
      },
