        ur: 'واضح کریں کہ اسٹرولر فولڈنگ ہے یا بڑا ہے، اور وہیل چیئر مینوئل فولڈنگ ہے یا موٹر والی، تاکہ ہماری ٹیم ڈگی کی گنجائش کو مدنظر رکھتے ہوئے اسٹاریا یا یوکون XL تجویز کر سکے۔',
        fr: 'Précisez si la poussette est pliable compacte ou volumineuse, et si le fauteuil roulant est manuel pliant ou électrique, afin que nos coordinateurs prévoient le volume adéquat avec un Staria ou Yukon XL.',
