          ar: 'يتم الاختيار بحسب عدد المسافرين وأحجام الحقائب: سيارة كامري لـ 1-3 ركاب مع حقيبتين، هيونداي ستاريا VIP للعائلات حتى 7 ركاب مع 5-6 حقائب، جمس يوكون XL VIP للفخامة القصوى وسعة 6-8 حقائب وكراسي متحركة، وتويوتا هايس للمجموعات حتى 11 راكباً.',
          en: 'Match vehicle capacity to your group size and baggage: Toyota Camry for 1-3 guests (2 bags), Hyundai Staria VIP for families up to 7 (5-6 bags), GMC Yukon XL VIP for luxury and 6-8 bags plus wheelchairs, and Toyota HiAce for up to 11 guests.',
          ms: 'Padankan saiz kenderaan mengikut bilangan penumpang dan bagasi: Sedan Camry untuk 1-3 penumpang (2 beg), Staria VIP untuk keluarga sehingga 7 orang (5-6 beg), GMC Yukon XL VIP untuk keselesaan 6-8 beg, dan Toyota HiAce sehingga 11 orang.',
          id: 'Sesuaikan jenis kendaraan dengan rombongan: Sedan Camry untuk 1-3 orang (2 koper), Hyundai Staria VIP untuk keluarga hingga 7 orang (5-6 koper), GMC Yukon XL VIP untuk kenyamanan ekstra 6-8 koper, dan Toyota HiAce untuk 11 orang.',
          ur: 'گاڑی کا انتخاب مسافروں اور سامان کی تعداد دیکھ کر کریں: کیمری 1-3 افراد (2 بیگز)، ہیونڈائی اسٹاریا 7 مسافروں تک (5-6 بیگز)، جی ایم سی یوکون ایکسٹرا لارج 6-8 بیگز اور وہیل چیئرز، اور ہائی ایس وین 11 مسافروں کے لیے موزوں ہے۔',
          fr: 'Choisissez selon le groupe et les bagages : Camry pour 1 à 3 passagers (2 valises), Hyundai Staria VIP jusqu’à 7 personnes (5-6 valises), GMC Yukon XL VIP pour le prestige et 6-8 bagages avec fauteuils, et Toyota HiAce jusqu’à 11 personnes.',
          es: 'Elija según pasajeros y maletas: Toyota Camry para 1-3 personas (2 maletas), Hyundai Staria VIP para familias de hasta 7 (5-6 maletas), GMC Yukon XL VIP para lujo y 6-8 maletas, y Toyota HiAce para grupos de hasta 11 viajeros.',
          de: 'Wählen Sie passend zu Gruppengröße und Gepäck: Toyota Camry für 1-3 Personen (2 Koffer), Hyundai Staria VIP für bis zu 7 Personen (5-6 Koffer), GMC Yukon XL VIP für Luxus und 6-8 Koffer, und Toyota HiAce Minibus bis zu 11 Gäste.',
          hi: 'यात्रियों और सामान के अनुसार वाहन चुनें: टोयोटा कैमरी 1-3 यात्रियों के लिए (2 बैग), हुंडई स्टारिया वीआईपी 7 लोगों तक (5-6 बैग), जीएमसी युकोन एक्सएल वीआईपी 6-8 बैग व व्हीलचेयर, और टोयोटा हाइस 11 यात्रियों तक के लिए उपयुक्त है।',
          tr: 'Yolcu ve bavul sayınıza göre araç seçin: 1-3 yolcu için Toyota Camry (2 bavul), 7 kişiye kadar Hyundai Staria VIP (5-6 bavul), 6-8 bavul ve tekerlekli sandalye için lüks GMC Yukon XL VIP ve 11 yolcuya kadar Toyota HiAce.',
