          id: 'Disarankan mengonfirmasi transportasi darat segera setelah tiket pesawat dan hotel selesai dipesan, khususnya pada musim ramai (Ramadhan dan liburan) agar tipe kendaraan idaman Anda terjamin ketersediaannya.',
          ur: 'بین الاقوامی پروازوں اور ہوٹلوں کی بکنگ فائنل ہوتے ہی ٹرانسپورٹ کنفرم کر لینا چاہیے، بالخصوص رمضان المبارک اور رش کے ایام میں تاکہ گاڑی کی دستیابی یقینی رہے اور ریٹ فکس ہو جائے۔',
