          de: 'Stimmen Sie das Fahrzeug auf Ihre Gruppe ab: Toyota Camry Limousine für 1-3 Personen (2 Koffer), Hyundai Staria VIP für bis zu 7 Personen (5-6 Koffer), GMC Yukon XL VIP für Luxus und 6-8 große Gepäckstücke, und Toyota HiAce für bis zu 11 Gäste.',
