          fr: 'Oui, tout à fait. C’est notre trajet le plus demandé. Votre vol est suivi en temps réel et votre chauffeur privé vous attend au terminal avec une pancarte à votre nom pour charger vos bagages et vous conduire sans escale à votre hôtel à La Mecque.',
