          en: 'Pricing depends on the vehicle category (sedan, family MPV, or full-size luxury SUV), travel distance between pickup and drop-off, and booking structure (fixed point-to-point transfer vs. hourly rental). All quoted rates are fixed and include fuel, highway tolls, and taxes.',
