          fr: 'Le tarif dépend de la catégorie de véhicule (berline, monospace familial ou SUV de luxe), de la distance parcourue et de la formule choisie (trajet direct à prix fixe ou mise à disposition horaire). Tous nos prix sont fermes et incluent carburant, péages et taxes.',
